import {ModelRuntime} from '@earendil-works/pi-coding-agent';import fs from 'node:fs';import path from 'node:path';
const dir=process.env.SDK_CONFIG_DIR,file=path.join(dir,'models.json');fs.mkdirSync(dir,{recursive:true});const model=id=>({id,name:id,api:'openai-completions',baseUrl:'https://base.invalid',reasoning:false,input:['text'],cost:{input:1,output:2,cacheRead:0,cacheWrite:0},contextWindow:4096,maxTokens:512});const config={p:{api:'openai-completions',baseUrl:'https://config.invalid',apiKey:'config',models:[{id:'custom'}],modelOverrides:{x:{name:'User',cost:{output:9}}}},q:{api:'openai-completions',baseUrl:'https://q.invalid',apiKey:'q',models:[{id:'q'}]}};
const pick=r=>r.getModels('p').map(m=>({id:m.id,name:m.name,baseUrl:m.baseUrl,cost:m.cost}));
try{fs.writeFileSync(file,JSON.stringify({providers:config}));const r=await ModelRuntime.create({modelsPath:file,refreshOnCreate:false,credentials:{read:async()=>undefined,list:async()=>[]}});const rows=[model('base')],native={id:'p',auth:{apiKey:{check:async()=>({type:'api_key'}),resolve:async()=>({auth:{apiKey:'native'},source:'native'})}},getModels:()=>rows,getAllModels:()=>rows};r.registerNativeProvider(native);const nativeRows=pick(r);rows.push(model('late'));const dynamic=pick(r);r.registerProvider('p',{api:'openai-completions',baseUrl:'https://ext.invalid',apiKey:'ext',models:[model('x')]});const extension=pick(r);r.registerProvider('p',{baseUrl:'https://second.invalid',models:undefined});const merged=pick(r);let rejected;try{r.registerProvider('p',{streamSimple(){}})}catch(error){rejected=error.message}const preserved=pick(r);r.unregisterProvider('p');const restored=pick(r);fs.writeFileSync(file,JSON.stringify({providers:{q:config.q}}));await r.refresh({providers:['q'],allowNetwork:false});const selected=pick(r);r.unregisterProvider('p');const removed=pick(r);await r.refresh({allowNetwork:false});const order=r.getProviders().map(p=>p.id).filter(id=>id==='p'||id==='q');console.log(JSON.stringify({nativeRows,dynamic,extension,merged,rejected,preserved,restored,selected,removed,order}))}finally{fs.unlinkSync(file)}
